const envelope=JSON.parse(JSON.stringify($node['Sub-workflow Input'].json));
const source=$json??{};
const raw=source.output??source.text??source.content?.[0]?.text??'';
const clean=s=>String(s??'').replace(/^\x60\x60\x60(?:json)?\s*/i,'').replace(/\x60\x60\x60$/,'').trim();
const apiError=source.error!=null||source.errorMessage!=null||source.executionError!=null;
const inquiryCategories=['Price Inquiry','Availability Inquiry','Test Drive Request','Financing/Loan Inquiry','Trade-In Inquiry','Service Inquiry','Warranty Inquiry','Managerial Review','Hidden Price Concern','Sarcasm / Frustration','Already Purchased','Closing','Negotiation','Delivery / Pickup','General Inquiry'];
const journeyIntents=['Visit Requested','Visit Booked','Managerial Review'];
const appointmentSignals=['NONE','INTEREST','ACCEPT','REJECT','BOOKED','CANCEL','RESCHEDULE'];
const businessFlows=['SALES','SERVICE','UNKNOWN'];
const requiredObjects=['customer','vehicle','language','inquiry','journey','communication','dnd','escalation','appointment','response_signals'];
const schemaValid=p=>p&&typeof p==='object'&&!Array.isArray(p)&&requiredObjects.every(k=>p[k]&&typeof p[k]==='object'&&!Array.isArray(p[k]))&&inquiryCategories.includes(p.inquiry.category)&&['High','Medium','Low'].includes(p.inquiry.confidence)&&(p.journey.intent===null||journeyIntents.includes(p.journey.intent))&&['Positive','Neutral','Negative'].includes(p.journey.sentiment)&&businessFlows.includes(p.business_flow)&&['sms','email','unknown'].includes(p.communication.preferred_mode)&&typeof p.communication.email_present==='boolean'&&typeof p.dnd.requested==='boolean'&&(p.dnd.reason===null||typeof p.dnd.reason==='string')&&typeof p.escalation.required==='boolean'&&typeof p.escalation.callback_requested==='boolean'&&appointmentSignals.includes(p.appointment.signal);
let parsed=null;let warning=null;
if(apiError){warning='OPENAI_API_ERROR';}else{try{const c=clean(raw);const start=c.indexOf('{');const end=c.lastIndexOf('}');parsed=JSON.parse(start>=0&&end>=start?c.slice(start,end+1):c);}catch(e){warning='MODEL_OUTPUT_PARSE_ERROR';}}
if(parsed&&!schemaValid(parsed)){warning='MODEL_OUTPUT_SCHEMA_ERROR';parsed=null;}
const msg=String(envelope.event?.content??'').replace(/[’‘]/g,"'");
const email=(msg.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]??null;
const vin=(msg.toUpperCase().match(/\b[A-HJ-NPR-Z0-9]{17}\b/)||[])[0]??null;
const clauses=msg.split(/(?:[.!?;,]|\s+[—–-]\s+|\bbut\b|\bhowever\b|\bthough\b|\byet\b)/i).map(s=>s.trim()).filter(Boolean);
const semanticSignal=pattern=>{let positive=false;let negated=false;for(const clause of clauses){const re=new RegExp(pattern.source,pattern.flags.includes('i')?'ig':'g');let match;while((match=re.exec(clause))){const before=clause.slice(Math.max(0,match.index-70),match.index);const isNegated=/(?:\b(?:do not|don't|dont|not|no|never|cannot|can't|cant|won't|wont|wouldn't|wouldnt|isn't|isnt|aren't|arent|wasn't|wasnt|without)\b(?:\s+\w+){0,6}|\bno need to(?:\s+\w+){0,4})\s*$/i.test(before);if(isNegated)negated=true;else positive=true;if(match[0].length===0)re.lastIndex++;}}return {positive,negated};};
const optOut=/^(?:stop|stopall|unsubscribe|end|quit)$/i.test(msg.trim())||/\bunsubscribe\b/i.test(msg)||/\b(?:stop|do not|don't|dont)\s+(?:text(?:ing)?|messag(?:e|ing)|contact(?:ing)?|call(?:ing)?)\s+me\b/i.test(msg)||/\b(?:remove|take)\s+me\s+(?:off|from)\s+(?:your\s+)?(?:texting|messaging|contact)?\s*list\b/i.test(msg);
const purchased=semanticSignal(/\b(?:already (?:bought|purchased)|bought (?:one )?elsewhere|no longer (?:shopping|in the market))\b/i);
const notInterested=semanticSignal(/\b(?:not interested|changed my mind)\b/i);
const callback=semanticSignal(/\b(?:call me|callback|call back|phone me|give me a call)\b/i);
const humanRequest=semanticSignal(/\b(?:manager|human|representative|salesperson|sales person)\b/i);
const urgent=semanticSignal(/\b(?:urgent|urgently|asap|immediately|right away)\b/i);
const upset=semanticSignal(/\b(?:upset|angry|furious|unacceptable|complaint|terrible experience|awful experience)\b/i);
const service=semanticSignal(/\b(?:service|repair|maintenance|oil change|brake|tire|mechanic|service department)\b/i);
const trade=semanticSignal(/\b(?:trade(?:[ -]?in)?|trade my|apprais(?:al|e))\b/i);
const finance=semanticSignal(/\b(?:financ(?:e|ing)|loan|apr|monthly payment|credit application|cosigner)\b/i);
const visitCancel=/\b(?:cancel|call off)\b.{0,24}\b(?:appointment|visit|test drive)\b|\b(?:cancel|call off) (?:my|the) (?:appointment|visit|test drive)\b/i.test(msg);
const visitReschedule=/\b(?:reschedul\w*|move|change)\b.{0,30}\b(?:appointment|visit|test drive|it)\b|\banother (?:day|time)\b/i.test(msg);
const visitReject=/\b(?:no|not|don't|dont|cannot|can't|wont|won't)\b.{0,30}\b(?:come in|visit|appointment|test drive|see (?:it|the car|the vehicle))\b/i.test(msg);
const booked=/\b(?:appointment|visit|test drive)\b.{0,28}\b(?:is|was|has been)\s+(?:booked|confirmed|scheduled)\b|\bconfirmed (?:appointment|visit|test drive)\b/i.test(msg);
const acceptedVisit=/\b(?:i(?:'ll| will) come|that (?:day|time|slot) works|see you (?:then|there|on|at))\b/i.test(msg);
const visitInterestSignal=semanticSignal(/\b(?:test drive|come (?:in|by|see)|visit (?:you|the|your)|see (?:it|the car|the vehicle|this vehicle)|schedule (?:a|an|the)?\s*(?:visit|test drive|appointment))\b/i);
const price=semanticSignal(/\b(?:price|how much|cost)\b/i);
const availability=semanticSignal(/\b(?:available|availability|in stock|still have)\b/i);
let deterministicAppointment=null;
if(visitCancel)deterministicAppointment='CANCEL';else if(visitReschedule)deterministicAppointment='RESCHEDULE';else if(visitReject)deterministicAppointment='REJECT';else if(booked)deterministicAppointment='BOOKED';else if(acceptedVisit)deterministicAppointment='ACCEPT';else if(visitInterestSignal.positive)deterministicAppointment='INTEREST';
let deterministicJourney=null;
if(humanRequest.positive||callback.positive||urgent.positive||upset.positive)deterministicJourney='Managerial Review';else if(booked)deterministicJourney='Visit Booked';else if(!visitReject&&!visitCancel&&(visitInterestSignal.positive||acceptedVisit||visitReschedule))deterministicJourney='Visit Requested';
let deterministicCategory=null;
if(purchased.positive)deterministicCategory='Already Purchased';else if(service.positive&&!trade.positive&&!finance.positive)deterministicCategory='Service Inquiry';else if(trade.positive&&!service.positive)deterministicCategory='Trade-In Inquiry';else if(finance.positive&&!service.positive)deterministicCategory='Financing/Loan Inquiry';else if(visitInterestSignal.positive&&/\btest drive\b/i.test(msg))deterministicCategory='Test Drive Request';else if(availability.positive)deterministicCategory='Availability Inquiry';else if(price.positive)deterministicCategory='Price Inquiry';
let deterministicFlow=null;
const salesPositive=trade.positive||finance.positive||visitInterestSignal.positive||availability.positive||price.positive;
if(service.positive&&!salesPositive)deterministicFlow='SERVICE';else if(salesPositive&&!service.positive)deterministicFlow='SALES';
const fallbackAppointment=deterministicAppointment??'NONE';
const fallbackJourney=deterministicJourney;
const fallback={customer:{name:envelope.context?.customer?.name??envelope.context?.lead?.name??null,email:email??envelope.context?.customer?.email??envelope.context?.lead?.email??null,phone:envelope.context?.customer?.phone??envelope.context?.lead?.phone??envelope.event?.sender??null},vehicle:{vin:vin??envelope.context?.lead?.vin??null,year:envelope.context?.lead?.year??null,make:envelope.context?.lead?.make??null,model:envelope.context?.lead?.model??null},language:{code:'en',name:'English',confidence:0},inquiry:{category:deterministicCategory??'General Inquiry',confidence:'Low'},journey:{intent:fallbackJourney,sentiment:(optOut||notInterested.positive||visitReject||upset.positive)?'Negative':'Neutral'},business_flow:deterministicFlow??'UNKNOWN',communication:{preferred_mode:/\bemail\b/i.test(msg)?'email':'unknown',email_present:!!email},dnd:{requested:optOut,reason:optOut?'opt_out':null},escalation:{required:humanRequest.positive||callback.positive||urgent.positive||upset.positive,reason:humanRequest.positive?'human_or_salesperson_request':callback.positive?'callback_request':urgent.positive?'urgent_need':upset.positive?'upset_or_complaint':null,callback_requested:callback.positive},appointment:{signal:fallbackAppointment,date:null,time:null},response_signals:{asks_location:/\b(?:where|address|location|directions)\b/i.test(msg),asks_booking_link:/\b(?:where|how|link)\b.*\b(?:book|appointment|schedule)\b/i.test(msg),asks_vdp_content:/\b(?:photo|picture|video|interior|exterior|feature|trim|accessor|carfax|autocheck|listing|spec|more info|more detail)\b/i.test(msg),complex_trade:/\b(?:kbb|trade.?in|loan payoff|appraisal)\b/i.test(msg)&&trade.positive,complex_finance:/\b(?:apr|zero down|cosigner|finance application|credit application)\b/i.test(msg)&&finance.positive,explicit_visit_refusal:visitReject,closure:/^(?:thanks|thank you|ok|okay|bye|got it)[!. ]*$/i.test(msg.trim())}};
const intel=parsed??fallback;
const coalesceFields=(model,known,fields)=>Object.fromEntries(fields.map(field=>[field,model?.[field]??known?.[field]??null]));
intel.customer=coalesceFields(intel.customer,fallback.customer,['name','email','phone']);
intel.vehicle=coalesceFields(intel.vehicle,fallback.vehicle,['vin','year','make','model']);
intel.language={...fallback.language,...(intel.language??{})};
intel.inquiry={...fallback.inquiry,...(intel.inquiry??{})};
intel.journey={...fallback.journey,...(intel.journey??{})};
intel.communication={...fallback.communication,...(intel.communication??{})};
intel.dnd={...fallback.dnd,...(intel.dnd??{})};
intel.escalation={...fallback.escalation,...(intel.escalation??{})};
intel.appointment={...fallback.appointment,...(intel.appointment??{})};
intel.response_signals={...fallback.response_signals,...(intel.response_signals??{})};
if(deterministicCategory)intel.inquiry.category=deterministicCategory;
if(deterministicFlow)intel.business_flow=deterministicFlow;
if(optOut){intel.dnd.requested=true;intel.dnd.reason=intel.dnd.reason??'opt_out';}
if(!intel.dnd.requested)intel.dnd.reason=null;
if(callback.positive){intel.escalation.callback_requested=true;intel.escalation.required=true;intel.escalation.reason=intel.escalation.reason??'callback_request';}
if(callback.negated){intel.escalation.callback_requested=false;if(intel.escalation.required&&/^callback/i.test(String(intel.escalation.reason??'')))intel.escalation.required=false;}
if(humanRequest.positive||urgent.positive||upset.positive){intel.escalation.required=true;intel.escalation.reason=intel.escalation.reason??(humanRequest.positive?'human_or_salesperson_request':urgent.positive?'urgent_need':'upset_or_complaint');}
if(deterministicJourney)intel.journey.intent=deterministicJourney;
if(visitReject||visitCancel)intel.journey.intent=null;
if(deterministicAppointment){intel.appointment.signal=deterministicAppointment;if(!['INTEREST','ACCEPT','BOOKED','RESCHEDULE'].includes(deterministicAppointment)){intel.appointment.date=null;intel.appointment.time=null;}}
intel.response_signals.explicit_visit_refusal=visitReject||intel.response_signals.explicit_visit_refusal;
if(email){intel.customer.email=intel.customer.email??email;intel.communication.email_present=true;}
if(vin)intel.vehicle.vin=vin;
intel.meta={parse_status:warning?'fallback':'parsed',warning,model:'gpt-5.6-luna',classified_at:new Date().toISOString()};
envelope.intelligence=intel;
return [{json:envelope}];

const e=JSON.parse(JSON.stringify($json));
const validJourney=['Visit Requested','Visit Booked','Managerial Review'];
const validAppointments=['NONE','INTEREST','ACCEPT','REJECT','BOOKED','CANCEL','RESCHEDULE'];
const validFlows=['SALES','SERVICE','UNKNOWN'];
if(e.intelligence?.journey?.intent!==null&&!validJourney.includes(e.intelligence?.journey?.intent))e.intelligence.journey.intent=null;
if(!validAppointments.includes(e.intelligence?.appointment?.signal))e.intelligence.appointment.signal='NONE';
if(!validFlows.includes(e.intelligence?.business_flow))e.intelligence.business_flow='UNKNOWN';
return [{json:e}];
